pub fn simpleHelp(params: []const ParamHelp) void {
        var max_spacing: usize = 2;
        _ = &max_spacing;
        var p_i: usize = 0;
        _ = &p_i;
        while ((p_i < params.len)) : (p_i = (p_i + 1)) {
