            var s_i: usize = 0;
            _ = &s_i;
            while ((s_i < num_spaces_after)) : (s_i = (s_i + 1)) {
                spaces_after[cp_cast_int(usize, s_i)] = 32;
            }
            _ = ((simplePrintParam(param)) catch unreachable);
            _ = Output.pretty("  {s}  {s}", .{ spaces_after, desc_text });
        }
}

