        var positional: ?Param(Id) = null;
        _ = &positional;
        var j: usize = 0;
        _ = &j;
        while ((j < params.len)) : (j = (j + 1)) {
            const param = params[@as(usize, @intCast(j))];
            if (((param.takes_value == .none) and (param.names.short != null))) {
                continue;
            }
            const prefix = (if ((param.names.short != null)) "-" else "--");
            var short_buf: [1]u8 = .{ 0 };
            _ = &short_buf;
            var name: []const u8 = "";
            _ = &name;
            if (param.names.short) |s| {
                _ = &s;
                short_buf[cp_cast_int(usize, 0)] = s;
                name = short_buf[0..1];
            } else {
                if (param.names.long) |l| {
                    _ = &l;
                    name = l;
                } else {
                    positional = param;
                    continue;
                }
            }
            if ((cos.bytes_written != 0)) {
                _ = try cs.writeByte(32);
            }
            _ = try cs.print("[{s}{s}", .{ prefix, name });
            switch (param.takes_value) {
.none => {

},
.one => {
_ = try cs.print(" <{s}>", .{ try valueText(context, param) });
},
.one_optional => {
_ = try cs.print(" <{s}>?", .{ try valueText(context, param) });
},
.many => {
_ = try cs.print(" <{s}>...", .{ try valueText(context, param) });
},
}
            _ = try cs.writeByte(93);
        }
        if (positional) |p| {
            _ = &p;
            if ((cos.bytes_written != 0)) {
                _ = try cs.writeByte(32);
            }
            _ = try cs.print("<{s}>", .{ try valueText(context, p) });
        }
}

pub fn usageEx(stream: anytype, comptime Id: type, params: []const Param(Id), valueText: anytype) !void {
        return usageFull(stream, Id, params, EmptyErr, .{ .valueText = valueText }, ctxValue);
}

pub fn usage(stream: anytype, params: []const ParamHelp) !void {
        _ = try usageEx(stream, Help, params, getValueSimple);
}
